public class Main {
  public static void main(String[] args) {
    System.out.println("1. Celsius vers Fahrenheit");
    System.out.println("2. Fahrenheit vers Celsius");
    System.out.println("0. Quitter");
  }
}

Scanner scanner = new Scanner(System.in);
System.out.print("Choix : ");
int choice = scanner.nextInt();
System.out.print("Température : ");
double value = scanner.nextDouble();

static double celsiusToFahrenheit(double celsius) {
  return celsius * 9.0 / 5.0 + 32.0;
}

switch (choice) {
  case 1 -> System.out.printf("%.2f °F%n", celsiusToFahrenheit(value));
  case 2 -> System.out.printf("%.2f °C%n", fahrenheitToCelsius(value));
  case 0 -> System.out.println("À bientôt");
  default -> System.out.println("Choix inconnu");
}
scanner.close();

static double calculateAverage(double[] grades) {
  if (grades.length == 0) return 0;
  double total = 0;
  for (double grade : grades) {
    total += grade;
  }
  return total / grades.length;
}

static double maximum(double[] grades) {
  double max = grades[0];
  for (double grade : grades) {
    if (grade > max) max = grade;
  }
  return max;
}

static int countPassed(double[] grades) {
  int count = 0;
  for (double grade : grades) {
    if (grade >= 10) count++;
  }
  return count;
}

System.out.printf("Moyenne : %.2f%n", calculateAverage(grades));
System.out.println("Minimum : " + minimum(grades));
System.out.println("Maximum : " + maximum(grades));
System.out.println("Réussites : " + countPassed(grades) + "/" + grades.length);
